INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'и представитъ сіе священникъ предъ Господа, и совершитъ жертву его за грјхъ и всесожженіе его.');
