INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Послј сего народъ отправился изъ Асироѕа, и остановился въ пустынј Фаранъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Тамъ говорилъ Господь Моисею, и сказалъ:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'пошли отъ себя людей, чтобъ они обозрјли землю Ханаанскую, которую Я даю сынамъ Израилевымъ, по одному человјку отъ колјна отцевъ ихъ пошлите всјхъ начальниковъ ихъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Моисей послалъ ихъ изъ пустыни Фаранъ, по повелјнію Господню, и всј сіи мужи были главные у сыновъ Израилевыхъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Вотъ имена ихъ: изъ колјна Рувимова Шаммуй, сынъ Закхуровъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'изъ колјна Симеонова Шафатъ, сынъ Хоріевъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'изъ колјна Іудина Халевъ, сынъ Іефонніинъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'изъ колјна Иссахарова Игалъ, сынъ Іосифовъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'изъ колјна Ефремова Осія, сынъ Навинъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'изъ колјна Веніаминова Фалтій, сынъ Рафуевъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'изъ колјна Завулонова Гаддіилъ, сынъ Содіевъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'изъ колјна Іосифова, изъ колјна Манассіина Гаддій, сынъ Сусіевъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'изъ колјна Данова Амміилъ, сынъ Гемалліевъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'изъ колјиа Асирова Сефуръ, сынъ Михаиловъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'изъ колјна Нефѕалимова Нахбій, сынъ Вофсіевъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'изъ колјна Гадова Геуилъ, сынъ Махіевъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Вотъ имена мужей, коихъ посылалъ Моисей для обозрјнія земли. И назвалъ Моисей Осію, сына Навина, Іисусомъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Когда посылалъ ихъ Моисей обозрјвать землю Ханаанскую, тогда сказалъ имъ: подите въ южную страну и взойдите на гору.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'И осмотрите землю, какова она, и народъ живущій на ней, силенъ ли онъ или слабъ, малочисленъ или многочисленъ?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Какова земля, на которой онъ живетъ, хороша ли она или худа; и каковы города, въ коихъ онъ живетъ, въ станахъ ли онъ живетъ или въ крјпостяхъ?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Какова земля, тучна ли она или суха? Есть ли на ней дерева или нјтъ? Будьте смјлы и возьмите плодовъ земли. А въ то время созрјвалъ первый виноградъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Они пошли и обозрјли землю отъ пустыни Цинъ даже до Рехова, при входј въ Емаѕъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Потомъ пошли въ южную страну и дошли до Хеврона, гдј жили Ахиманъ, Шемай и Ѕалмай, дјти Енаковы: Хевронъ же построенъ былъ семью годами прежде Цоана Египетскаго.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'И пришли къ долинј Есхолъ и срјзали тамъ виноградную вјтвь съ кистью ягодъ, которую несли на носилкахъ двое; также взяли гранатовыхъ яблокъ и смоквей.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Мјсто сіе назвали долиною Есхолъ, по причинј виноградной кисти, которую срјзали тамъ сыны Израилевы.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'По прошествіи сорока дней возвратились они, обозрјвъ землю,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'и пошли и пришли къ Моисею и Аарону, и ко всему обществу сыновъ Израилевыхъ въ пустыню Фаранъ, въ Кадесъ, и принесли имъ и всему обществу отвјтъ, и показали имъ плоды земли.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'И разсказывали ему, и говорили: мы ходили въ землю, въ которую ты посылалъ насъ, въ ней течетъ молоко и медъ, и вотъ плоды ея;');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'только народъ живущій на землј той силенъ, и города укрјпленные, весьма большіе, да и сыновъ Енаковыхъ мы видјли тамъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Амаликъ живетъ на южной части земли, Хеттеи, и Іевусеи и Аморреи живутъ на горј; Хананеи же живутъ подлј моря и подлј Іордана.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Халевъ между тјмъ успокоивалъ народъ предъ Моисеемъ, говоря: пойдемъ и завладјемъ ею, потому что мы можемъ преодолјть ее.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'А тј, которые ходили съ нимъ, говорили: не можемъ идти къ народу сему, поелику онъ сильнје насъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Притомъ распускали худую молву о землј, которую они осматривали, между сынами Израилевыми, говоря: земля, которую проходили мы для обозрјнія, есть земля поядающая живушихъ на ней, и весь народъ который видјли мы среди ея, суть люди великорослые.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Тамъ видјли мы и исполиновъ, сыновъ Енаковыхъ, отъ исполинскаго рода; въ глазахъ нашихъ мы были предъ ними, какъ саранча, таковыми же были и въ глазахъ ихъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Тогда все общество подняло вопль, и плакалъ народъ въ ту ночь.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'И стали роптать на Моисея и Аарона всј сыны Израилевы, и все общество сказало имъ: о если бы мы умерли въ землј Египетской, или умерли бы въ пустынј сей!');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'И для чего Господь ведетъ насъ въ землю сію, чтобы мы пали отъ меча? Жены наши и дјти наши достанутся въ добычу врагамъ. Не лучше ли намъ возвратиться въ Египетъ?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'И сказали другъ другу: поставимъ надъ собою начальника, и возвратимся въ Египетъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Моисей и Ааронъ пали на лица свои предъ всјмъ собраніемъ общества сыновъ Израилевыхъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'И Іисусъ, сынъ Навинъ, и Халевъ, сынъ Іефонніинъ, изъ обозрјвавшихъ землю, разодрали одежды свои,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'и сказали всему обществу сыновъ Израилевыхъ: земля, которую мы проходили для обозрјнія, есть земля самая лучшая.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Если любитъ насъ Господь, то введетъ насъ въ землю сію и дастъ вамъ сію землю, въ которой течетъ молоко и медъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'Только противъ Господа не возставайте, и не бойтесь народа земли сей: поелику онъ достанется намъ на съјденіе, защиты у нихъ не стало; а съ нами Господь, не бойтесь ихъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'Все общество положило побить ихъ камнами; но слава Господня явилась въ скиніи собранія всјмъ сынамъ Израилевымъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'И сказалъ Господь Моисею: доколј будетъ пренебрегать Меня народъ сей, и доколј не будетъ Мнј вјрить при всјхъ тјхъ знаменіяхь, которыя дјлалъ Я среди его?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Итакъ поражу его язвою и истреблю его, и произведу отъ тебя народъ, который больше и сильнје его.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Но Моисей сказалъ Господу: Египтяне слышали, что Ты силою Твоею вывелъ народъ сей изъ среды ихъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'и сказали жителямъ земли сей; они также слышали, что Ты Господь находишься среди народа сего, и что Ты Господь даешь видјть Себя лицемъ къ лицу, и облако Твое стоитъ надъ ними, и Ты идешь предъ ними днемъ въ столпј облачномъ, а ночью въ столпј огненномъ;');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'если же Ты истребишь народъ сей, какъ одного человјка: то народы, которые слышали славу Твою, скажутъ:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Господь, не имјя силъ ввести народъ сей въ землю, которую Онъ съ клятвою објщалъ ему, погубилъ его въ пустынј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Итакъ да возвеличится сила Господня, какъ Ты говорилъ, и сказалъ:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Господь медленъ на гнјвъ, и великъ въ милости, прощаетъ беззаконія и преступленія, но виновнаго не оставляетъ безъ наказанія, наказываетъ беззаконіе отцевъ въ сынахъ до третьяго и четвертаго рода.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'Прости грјхъ народу сему по великой милости твоей, такъ какъ Ты прощалъ народъ сей отъ Египта даже доселј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'И сказалъ Господь: прощаю по слову твоему.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Но живъ Я, и славы Господней полна вся земля:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'всј, которые видјли славу Мою и знаменія Мои, сдјланныя Мною въ Египтј и въ пустынј, и искушали меня уже десять разъ и не слушали гласа Моего,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'не увидятъ земли, которую Я съ клятвою објщалъ отцамъ ихъ: всј пренебрегшіе Меня не увидятъ ея.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'Но раба Моего Халева за то, что въ немъ былъ иной духъ, и онъ совершенно повиновался мнј, введу въ землю, въ которую онъ ходилъ, и сјмя его получитъ ее въ наслјдство.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Но поелику Амаликитяне и Хананеи живутъ на равнинј, то завтра возвратитесь и идите въ пустыню, къ Чермному морю.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'И говорилъ Господь Моисею и Аарону, и сказалъ:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'доколј буйному сему обществу роптать на Меня? Ропотъ сыновъ Израилевыхъ, которымъ они ропщутъ на Меня, Я слышу.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Скажи имъ: живъ Я, говоритъ Господь; что говорили вы въ слухъ Мнј, то и сдјлаю вамъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Въ пустынј сей падутъ тјла ваши, всј вошедшіе у васъ въ перепись, сколько васъ числомъ, отъ двадцати лјтъ и выше, которые роптали на Меня.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Вы не войдете въ землю, на которой Я, подъемля руку Мою, клялся поселить васъ, кромј Халева, сына Іефонніина, и Іисуса, сына Навина.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Дјтей вашихъ, о которыхъ вы говорили, что они достанутся въ добычу врагамъ, Я введу туда и они узнаютъ землю, которую вы презрјлн.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'А ваши трупы падуть въ пустынј сей.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Впрочемъ сыны ваши будутъ пастушескую жизнь вести въ пустынј сорокъ лјтъ, и будутъ нести наказаніе за блудодјйство ваше, пока не падутъ всј тјла ваши въ пустынј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'По числу сорока дней, въ которые вы обозрјвали землю, вы понесете наказаніе за грјхи ваши сорокъ лјтъ, годъ за день, дабы вы познали, что значитъ быть оставленнымъ Мною.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Я Господь говорю, и такъ поступлю со всјмъ буйнымъ симъ обществомъ, возставшимъ противъ Меня: въ пустынј сей всј падутъ и перемрутъ въ ней.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'А тј, которыхъ посылалъ Моисей для обозрјнія земли, и которые возвратившись, возмутили противъ него все сіе общество, распуская худую молву о землј:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'сіи, распустившіе худую молву о землј, умерли, бывъ поражены предъ Господомъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Только Іисусъ, сынъ Навинъ, и Халевъ, сынъ Іефонніинъ, остались живы изъ тјхъ мужей, которые ходили обозрјвать землю.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Когда Моисей сказалъ слова сіи предъ всјми сынами Израилевыми, тогда горько заплакалъ народъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Вставъ рано поутру, пошли на вершину горы, говоря: вотъ, мы пойдемъ на то мјсто, о которомъ сказалъ Господь, поелику мы согрјшили.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Но Моисей сказалъ: для чего вы преступаете повелјніе Господне? Это будетъ безуспјшно. [(Numbers 15:42) Не ходите; ибо нјтъ среди васъ Господа, чтобы не поразили васъ враги ваши.] [(Numbers 15:43) Ибо Амаликитяне и Хананеи тамъ предъ вами, и вы падете отъ меча, потому что вы отступили отъ Господа и не будетъ съ вами Господа.] [(Numbers 15:44) Но они не смотря на сіе взошли на вершину горы; ковчегъ же завјта Господня и Моисей не выходили изъ стана.] [(Numbers 15:45) Тогда Амаликитяне и Хананеи, живущіе на горј той, сошли, били ихъ и гнали ихъ до Хормы.]');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'И говорилъ Господь Моисею, и сказалъ:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'объяви сынамъ Израилевымъ, и скажи имъ: когда вы войдете въ землю, которую Я даю вамъ въ жилище,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'и принесете Господу огнепалимую жертву, всессоженіе, или жертву закалаемую, во исполненіе објта, или по усердію, или въ праздники ваши, дабы сдјлать благоуханіе успокоенія Господу отъ крупнаго или мелкаго скота:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'тогда приносящій жертву свою Господу долженъ принесть въ приношеніе хлјбное десятую часть ефы пшеничной муки, облитой четвертою частію гина елея.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'И вина для возліянія приноси четвертую часть гина при всесожженіи, или при закалаемой жертвј, на каждаго агнца.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'А принося овна, приноси въ приношеніе хлјбное двј десятыхъ части ефы пшеничной муки, облитой третьею частію гина елея.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'И вина для возліянія приноси третью часть гина въ благоуханіе успокоенія Господу.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Если изъ крупнаго скота приносишь всесожженіе, или жертву закалаемую, во исполненіе објта или въ благодареніе Господу:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'то вмјстј съ жертвою изъ крупнаго скота должно принести приношенія хлјбнаго три десятыхъ части ефы пшеничной муки, облитой половиною гина елея.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'И вина для возліянія приноси полгина въ огнепалимую жертву, въ благоуханіе успокоенія Господу.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Такъ должно дјлать при каждомъ тельцј, и при каждомъ овнј, и при агнцј изъ овецъ или козъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Смотря по числу жертвъ, которыя вы приносите, такъ дјлайте при каждой, смотря по числу ихъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Всякой природный житель земли долженъ дјлать сіе такъ, принося огнепалимую жертву въ благоуханіе успокоенія Господу.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'И если будетъ между вами жить пришлецъ, или будетъ кто среди васъ въ роды ваши, и принесетъ огнепалимую жертву въ благоуханіе успокоенія Господу: то и онъ долженъ дјлать такъ, какъ вы дјлаете.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Для васъ, общество, и для пришельца, живущаго у васъ, постановленіе одно; постановленіе вјчное въ роды ваши: что вы, то и пришлецъ да будетъ предъ Господомъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Законъ одинъ и одни права да будутъ для васъ и для пришельца, живущаго у васъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'И говорилъ Господь Моисею, и сказалъ:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'объяви сынамъ Израилевымъ, и скажи имъ: когда вы войдете въ землю, въ которую Я веду васъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'и будете јсть хлјбъ той земли: то возносите возношеніе Господу.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Начатокъ тјста вашего, лепешку вознесите въ возношеніе: вознесите ее такъ, какъ возношеніе съ гумна.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Начатокъ тјста вашего отдавайте въ возношеніе Господу въ роды ваши.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Если же преступите по ошибкј, и не исполните всјхъ сихъ заповјдей, которыя изрекъ Господь Моисею,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'всего, что заповјдалъ вамъ Господь чрезъ Моисея, отъ того дня, въ который Господь далъ вамъ заповјди, и впредь въ роды ваши:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'то, если по неусмотрјнію общества сдјлана ошибка, пусть все общество принесетъ одного тельца изъ крупнаго скота во всесожженіе, въ благоуханіе успокоенія Господу, вмјстј съ хлјбнымъ приношеніемъ и возліяніемъ его по установленію и одного козла въ жертву за грјхъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'И очиститъ священникъ все общество сыновъ Израилевыхъ, и будетъ прощено имъ; поелику это была ошибка, и они принесли приношеніе свое въ огнепалимую жертву Господу, и совершили предъ лицемъ Господа жертву за грјхъ, сдјланный по ошибкј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'И будетъ прощено всему обществу сыновъ Израилевыхъ, и пришельцу, живущему у васъ; поелику весь народъ находился во грјхј, сдјланномъ по ошибкј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Если же одинъ кто согрјшитъ по ошибкј: то пусть принесетъ козу однолјтнюю въ жертву за грјхъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'И очиститъ священникъ душу, сдјлавшую по ошибкј грјхъ предъ Господомъ, и очищена будетъ, и прощено будетъ ей.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Одинъ законъ да будетъ для васъ, какъ для природнаго жителя изъ сыновъ Израилевыхъ, такъ и для пришельца, живущаго у васъ, если кто сдјлаетъ что по ошибкј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Если же кто изъ природныхъ жителей, или изъ пришельцевъ, дерзкою рукою сдјлаетъ что, то онъ хулитъ Господа: истребится душа та изъ народа своего.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Ибо онъ слово Господне презрјлъ и заповјдь Его нарушилъ: истребится душа та, грјхъ ея на ней.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'Когда сыны Израилевы были въ пустынј, нашли одного человјка, собиравшаго дрова въ день субботы.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'И привели его нашедшіе его, собирающаго дрова, къ Моисею и Аарону и ко всему обществу.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Они посадили его подъ стражу, потому что не было еще ясно опредјлено, что должно съ нимъ сдјлать.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'И сказалъ Господь Моисею: долженъ умереть человјкъ сей; пусть побьетъ его камнями все общество внј стана.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'И вывело его все общество вонъ изъ стана, и побило его камнями, и онъ умеръ, какъ повелјлъ Господь Моисею.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'И сказалъ Господь Моисею:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'объяви сынамъ Израилевьмъ, и скажи имъ: чтобъ они дјлали у себя кисти на краяхъ одежды своей въ роды ихъ, и къ кисти, которая на краяхъ, пришивали нить яхонтоваго цвјта.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Эта кисть у васъ будетъ для того, чтобы вы, смотря на нее, вспомнили всј заповјди Господни, и исполняли ихъ, и не ходили вслјдъ сердца вашего и очей вашихъ, чтобы блудодјйно послјдовать имъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'для того, чтобы вы помнили и исполняли всј заповјди Мои, и были святы предъ Богомъ вашимъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Я Господь, Богъ вашъ, Который вывелъ васъ изъ земли Египетской, чтобы быть вамъ Богомъ: Я Господь, Богъ вашъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, '');
