INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'И сказалъ Господь Аарону: ты и сыны твои и домъ отца твоего понесете на себј грјхъ за неисправность во святилищј; и ты и сыны твои съ тобою понесете на себј грјхъ за неисправность въ священствј своемъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'И братьевъ твоихъ колјно Левіино, племя отца твоего, возьми себј, пусть они будутъ при тебј и служатъ тебј; а ты и сыны твои будете при скиніи откровенія.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Пусть они соблюдаютъ, что должно соблюдать для тебя и для всей скиніи, только, чтобъ не приступали къ сосудамъ святилища и къ жертвеннику, чтобъ не умереть и имъ и вамъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Пусть они будутъ при тебј и соблюдаютъ, что должно соблюдать при скиніи собранія касательно всякихъ работъ при скиніи; а посторонній не долженъ приближаться къ вамъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'И имјйте такимј образомъ въ соблюденіи святилище и жертвенникъ, дабы не было впредь гнјва на сыновъ Израилевыхъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'И6о братьевъ вашихъ левитовъ Я взялъ отъ сыновъ Израилевыхъ; вамъ въ даръ даны они отъ Господа, дабы отправляли работы при скиніи собранія.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'А ты и сыны твои съ тобою соблюдайте должностъ священства вашего во всемъ, что касается до жертвенника, и до того, что отправляется внутри за завјсою, и служите; вамъ въ даръ даю Я священство, служеніе ваше, и если приступитъ кто посторонній, преданъ будетъ смерти.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'И говорилъ Господь Аарону: вотъ Я поручаю тебј наблюдать за возношеніями Мнј приносимыми; изъ всего посвящаемаго сынами Израилевыми даю часть тебј и сынамъ твоимъ въ вјчный участокъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Вотъ что принадлежитъ тебј изъ великихъ святынь съ огня: все приносимое ими во всякое приношеніе хлјбное и во всякую жертву за грјхи ихъ, и во всякую жертву повинности, что они принесутъ Мнј это великая святыня тебј и сынамъ твоимъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'На святјйшемъ мјстј јшьте сіе, всј мужескаго пола могутъ јсть. Это святынею да будетъ для тебя.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'И вотъ что принадлежитъ тебј изъ возношеній ихъ: все, приносимое сынами Израилевыми, чрезъ потрясаніе, даю тебј и сынамъ твоимъ, и дочерямъ твоимъ съ тобою, въ вјчный участокъ. Всякій чистый въ дому твоемъ можетъ јсть сіе.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Все лучшее изъ елея и все лучшее изъ винограда и хлјба, начатки ихъ, которые они даютъ Господу, тебј отдаю.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Всј первыя произведенія земли ихъ, которыя они принесутъ Господу, тебј принадлежатъ. Всякій чистый въ дому твоемъ можетъ јсть сіе.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Все, заклятое въ землј Израилевой, тебј принадлежитъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Все, разверзающее ложесна у всякой плоти, которую приносятъ Господу, изъ людей и изъ скота, тебј принадлежитъ. Только за первенца человјческаго возьми выкупъ, и за первородное изъ скота нечистаго возьми выкупъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'А выкупъ за нихъ: начиная отъ одного мјсяца по оцјнкј твоей бери выкупъ пять сиклей серебра противъ сикля святилища, который въ двадцать геръ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Только за первородное изъ воловъ, и за первородное изъ овецъ, и за первородное изъ козъ не бери выкупа: они святыня; кровію ихъ окропляй жертвенникъ, и тукъ ихъ сожигай въ огнепалимую жертву, въ благоуханіе успокоенія Господу.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Мясо же ихъ тебј принадлежитъ, такъ какъ грудь потрясанія и правое плечо тебј принадлежатъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Всј возносимыя святыни, которыя возносятъ сыны Израилевы Господу, отдаю тебј и сынамъ твоимъ и дочерямъ твоимъ съ тобою въ вјчный участокъ. Это вјчный завјтъ соли у Господа, данный тебј и сјмени твоему съ тобою.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'И сказалъ Господь Аарону: въ землј ихъ не будешь имјть удјла и части не будетъ тебј между ними. Я часть твоя и удјлъ твой среди сыновъ Израилевыхъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'А сынамъ Левіи, вотъ Я даю въ удјлъ десятину изъ всего, что у Израиля, за работы ихъ, за то, что они отправляютъ работы въ скиніи собранія.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Сыны Израилевы не должны впередъ приступать къ скиніи собранія, чтобъ не понести грјха и не умереть, [(Numbers 19:23) Пусть левиты исправляютъ работы въ скиніи собранія, и несутъ на себј грјхъ ихъ. Это постановленіе вјчное въ роды ваши; среди сыновъ Израилевыхъ не получатъ они удјла.] [(Numbers 19:24) Поелику десятину сыновъ Израилевыхъ, которую они приносятъ въ возношеніе Господу, Я отдаю левитамъ въ удјлъ, потому и сказалъ Я имъ: между сынами Израилевыми они не получатъ удјла.] [(Numbers 19:25) И говорилъ Господь Моисею, и сказалъ:] [(Numbers 19:26) объяви левитамъ и скажи имъ: когда вы будете брать отъ сыновъ Израилевыхъ десятину, которую Я даю вамъ отъ нихъ въ удјлъ: то возносите изъ ней возношеніе Господу, десятину изъ десятины.] [(Numbers 19:27) И вмјнено будетъ вамъ сіе возношеніе ваше, какъ бы хлјбъ съ гумна и какъ бы приношеніе изъ точила.] [(Numbers 19:28) Такимъ образомъ и вы будете возносить возношеніе Господу изъ всјхъ десятинъ вашихъ, которыя будете брать отъ сыновъ Израилевыхъ, и будете давать изъ нихъ возношеніе Господу для Аарона священника.] [(Numbers 19:29) Изъ всего даемаго вамъ возносите возношеніе Господу и изъ всего лучшаго святыню для Него.] [(Numbers 19:30) И скажи имъ: когда вы принесете изъ сего лучшее, то сіе вмјнено будетъ левитамъ, какъ бы получаемое съ гумна, и получаемое отъ точила.] [(Numbers 19:31) Вы можете јсть сіе на всякомъ мјстј, вы и семейства ваши; ибо это вамъ плата за работы ваши въ скиніи собранія.] [(Numbers 19:32) Тогда не понесете за сіе грјха, когда принесете лучшее изъ сего; и посвящаемаго сынами Израилевыми не оскверните, и не умрете.]');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'И говорилъ Господь Моисею и Аарону, и сказалъ:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'вотъ постановленіе закона, который повелјлъ дать Господь, говоря: скажи сынамъ Израилевымъ, пусть приведутъ тебј рыжую телицу безъ порока, у которой нјтъ недостатка, на которой не было ярма.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'И отдайте ее Елеазару священнику, а онъ пусть выведетъ ее вонъ изъ стана и прикажетъ заколоть ее при себј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'И пусть возьметъ Елеазаръ священникъ перстомъ своимъ крови ея, и кровію ея семь разъ покропитъ предъ скиніею собранія.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Телицу же сожгутъ при его глазахъ: кожу ея, мясо ея, и кровь ея съ нечистотою ея пусть сожгутъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'И пусть возьметъ священникъ кедроваго дерева и иссопъ, и червленую нить, и броситъ на сожигаемую телицу.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'И пусть вымоетъ священникъ одежды свои, и омоетъ тјло свое водою, и потомъ войдетъ въ станъ, и нечистъ будетъ священникъ до вечера.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Равно и сожигавшій ее пусть вымоетъ одежды свои водою, и омоетъ тјло свое водою и нечистъ будетъ до вечера.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Тогда кто-нибудь чистый пусть соберетъ пепелъ телицы и положитъ внј стана на чистомъ мјстј, и онъ долженъ быть въ сохраненіи у общества сыновъ Израилевыхъ для воды очистительной: это жертва за грјхъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'И собиравшій пепелъ телицы пусть вымоетъ одежды свои, и нечистъ будетъ до вечера. Сіе для сыновъ Израилевыхъ и для пришельцевъ, живущихъ у нихъ, да будетъ постановленіемъ вјчнымъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Прикоснувшійся къ мертвому тјлу какого-либо человјка нечистъ будетъ семь дней.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Онъ долженъ очистить себя сею водою въ третій день и въ седьмой день, и будетъ чистъ; если же онъ не очиститъ себя въ третій и седьмой день, то не будетъ чистъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Всякій прикоснувшійся къ мертвому тјлу какого-либо человјка умершаго, и не очистившій себя, осквернитъ жилище Господа, истребится человјкъ тотъ изъ среды Израиля: поелику онъ не окропленъ очистительною водою, онъ нечистъ, еще нечистота его на немъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Вотъ законъ: если человјкъ умретъ въ шатрј, то всякій, кто придетъ въ шатеръ, и всякій, кто находится въ шатрј, нечистъ будетъ семь дней.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Всякій открытый сосудъ, который не обвязанъ и не покрытъ, нечистъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Всякій, кто прикоснется на полј къ убитому мечемъ, или къ умершему, или къ кости человјческой, или ко гробу, нечистъ будетъ семь дней.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Для очищенія нечистаго пусть возьмутъ пепла сожженной оной жертвы за грјхъ, и нальютъ на него живой воды въ сосудъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Потомъ кто-нибудь чистый пусть возьметъ иссопъ, и омочитъ его въ водј, и окропитъ шатеръ и всј сосуды и людей, которые находятся въ немъ, и прикоснувшагося къ кости, или къ убитому или къ умершему, или ко гробу.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'И пусть окропитъ чистый нечистаго въ третій и седьмой день, и очиститъ его въ седьмой день. Тогда пусть вымоетъ онъ одежды свои, и омоетъ себя водою, и къ вечеру будетъ чистъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Если же кто-нибудь нечисть и не очиститъ себя, то истребится человјкъ тотъ изъ среды народа: поелику онъ оскверняетъ святилище Господа, очистительною водою онъ не окропленъ, онъ нечистъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'И да будетъ сіе для нихъ постановленіеиъ вјчнымъ. Также и кропившій сею очистительною водою, пусть вымоетъ одежды свои, и прикоснувшійся къ очистительной водј нечистъ будетъ до вечера.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'И все, къ чему нрикоснется нечистый, будетъ нечисто; и прикоснувшійся къ нему человјкъ нечистъ будетъ до вечера.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'пришли сыны Израилевы, все общество, въ пустыню Цинъ въ первый мјсяцъ, и остановился народъ въ Кадесј, и умерла тамъ Маріамъ, и погребена тамъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'И не было воды для общества, и собрались они противъ Моисея и Аарона,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'и вступилъ народъ въ ссору съ Моисеемъ и сказалъ: о если бы умерли тогда и мы, когда умерли братья наши предъ Господомъ!');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Зачјмъ вы привели народъ Господень въ сію пустыню, чтобъ умереть здјсь и намъ и скоту нашему?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'И для чего вывели вы насъ изъ Египта, чтобы привести насъ на это негодное мјсто, гдј нјтъ ни хлјба, ни смоковницъ, ни винограда, ни гранатовыхъ яблоковъ, ни воды для питья?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'И пошелъ Моисей и Ааронъ отъ народа къ дверямъ скиніи собранія, и пали на лица свои, и явилась имъ слава Господня.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'И говорилъ Господь Моисею, и сказалъ:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'возьми посохъ и собери общество, ты и Ааронъ братъ твой, и скажите при глазахъ ихъ скалј, и она дастъ изъ себя воду: такимъ образомъ ты источишь имъ воду изъ скалы, и напоишь общество сіе и скотъ его.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Моисей взялъ посохъ отъ Господа, такъ, какъ Онъ повелјлъ ему.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'И собрали Моисей и Ааронъ народъ къ скалј, и сказалъ онъ имъ: послушайте, мятежники, развј намъ изъ скалы сей источить для васъ воду?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'И поднялъ Моисей руку свою и ударилъ въ скалу посохомъ своимъ дважды и потекло много воды, и пило общество и скотъ его.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'И сказалъ Господь Моисею и Аарону: за то, что вы не повјрили Мнј, и не явили святости Моей очамъ сыновъ Израилевыхъ, не введете народа сего въ землю, которую Я даю ему.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Это вода Меривы, у которой вошли въ распрю сыны Израилевы съ Господомъ, и Онъ явилъ имъ святость Свою.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Изъ Кадеса послалъ Моисей пословъ къ царю Едомскому, чтобъ сказать: такъ говоритъ братъ твой Израиль: ты знаешь всј изнурительные труды, которые постигли насъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Отцы наши перешли въ Египетъ, и мы жили въ Египтј много времени, и худо поступали Египтяне съ нами и отцами нашими.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Тогда мы воззвали ко Господу и услышалъ Господь гласъ нашъ, и послалъ ангела и вывелъ насъ изъ Египта. И вотъ, мы въ Кадесј, городј, лежащемъ при самомъ предјлј твоемъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Позволь намъ пройдти землею твоею, мы не пойдемъ по полямъ, и по виноградникамъ, и не будемъ пить воды изъ колодезей, но пойдемъ дорогою царскою, не своротимъ ни направо ни налјво, пока не перейдемъ твоихъ предјловъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Но Едомъ сказалъ ему: не ходи черезъ меня, иначе я съ мечемъ выступлю противъ тебя.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'И сказали ему сыны Израилевы: мы пойдемъ большою дорогою, и если будемъ пить твою воду, я и скотъ мой, то буду платить за нее; только ногами моими пройду, что ничего не стоитъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'Но онъ сказалъ: не ходи; и выступилъ противъ него Едомъ съ многочисленнымъ народомъ и съ сильною рукою.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Когда такимъ образомъ не согласился Едомъ позволить Израилю пройдти чрезъ его предјлы, Израиль пошелъ въ сторону отъ него.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Отправясь изъ Кадеса, сыны Израилевы, все общество, пришли къ горј Оръ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'И сказалъ Господь Моисею и Аарону на горј Оръ, у предјловъ земли Едомской:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'пусть отойдетъ Ааронъ къ народу своему: ибо онъ не войдетъ въ землю, которую Я даю сынамъ Израилевымъ, за то, что вы непокорны были повелјнію Моему у водъ Меривы.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Возьми Аарона и Елеазара, сына его, и возведи ихъ на гору Оръ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Тамъ сними съ Аарона одежды его и облеки въ нихъ Елеазара сына его, и пусть Ааронъ отойдетъ и умретъ тамъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Моисей сдјлалъ такъ, какъ повелјлъ Господь; взошли они на гору Оръ въ глазахъ всего общества.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'И снялъ Моисей съ Аарона одежды его и облекъ въ нихъ Елеазара, сына его. И умеръ тамъ Ааронъ на вершинј горы, а Моисей и Елеазаръ сошли съ горы.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'И увидјло все общество, что Ааронъ умеръ, и оплакивалъ Аарона весь домъ Израилевъ тридцать дней.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Хананейскій царь Арада, живущій къ югу, услышавъ, что Израиль идетъ дорогою отъ Аѕарима, вступилъ въ сраженіе съ Израильтянами, и нјсколько изъ нихъ взялъ въ плјнъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Тогда Израиль далъ објтъ Господу, и сказалъ: если предашь народъ сей въ руки мои, то положу заклятіе на города ихъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Господь услышалъ гласъ Израиля и предалъ Хананеевъ, и онъ положилъ заклятіе на нихъ и на города ихъ; почему и наречено имя мјсту тому: Хорма.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Отъ горы Оръ отправились они въ путь держась Чермнаго моря, чтобы миновать землю Едома. На пути показалъ народъ свое малодушіе.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'И говорилъ народъ противъ Бога и противъ Моисея: зачјмъ вывели вы насъ изъ Египта, чтобъ умереть намъ въ пустынј; ибо здјсь нјтъ ни хлјба, ни воды, и душј нашей опротивјлъ этотъ негодный хлјбъ?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'И послалъ Господь на народъ ядовитыхъ змјевъ, которые угрызали народъ, и умерло у Израиля много народа.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'И пришелъ народъ къ Моисею и сказалъ: согрјшили мы, что говорили противъ Господа, и противъ тебя; помолись Господу, чтобъ онъ отогналъ отъ насъ змјевъ. И помолился Моисей о народј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'И сказалъ Господь Моисею: сдјлай себј змјя, и повјсь его на шестъ; и будетъ, что всякій угрызенный, взглянувъ на него, останется живъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'И сдјлалъ Моисей мјднаго змјя и повјсилъ его на шестъ, и когда угрызалъ змјй человјка, онъ, взглянувъ на мјднаго змјя, оставался живъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'И отправились сыны Израилевы, и остановились въ Овоѕј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Отправившись изъ Овоѕа, остановились въ Іе-Аваримј, въ пустынј, что противъ Моава, къ востоку солнца.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Оттуда отправились и остановились на долинј Заредъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Отправившись отсюда, остановились по ту сторону Арнона, который по пустынј течетъ отъ предјловъ Аморрея; ибо Арнонъ составляетъ предјлъ Моава, отдјляющій Моавитянъ отъ Аморреевъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Потому и сказано въ книгј Браней Господнихъ: Вагебъ въ Суфј и потоки Арнона.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'И мјсто, гдј вытекаютъ потоки, которое лежитъ къ Шебетъ-Ару и прилегаетъ къ предјламъ Моава.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'А отсюда - въ Бееръ. Это тотъ колодезь, о которомъ Господь сказалъ Моисею: собери народъ, и дамъ имъ воды.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Тогда воспјлъ Израиль пјснь сію: Наполняйся колодезь, воспойте о немъ,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Колодезь, который выкопали князи, вырыли вожди народа съ законодателемъ посохами своими. Изъ пустыни отправилисъ въ Матанну,');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Изъ Матанны въ Нагаліилъ, изъ Нагаліила въ Вамоѕъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Изъ Вамоѕа въ Гай, который въ землј Моава, на вершинј горы Фазги, обращенной лицемъ къ пустынј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Отсюда Израиль послалъ пословъ къ Сигону, царю Аморрейскому, чтобъ сказать:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'позволь мнј пройдти землею твоею, не будемъ заходить въ поля и виноградники, не будемъ пить воды изъ колодезей, а пойдемъ путемъ царскимъ, пока не перейдемъ предјловъ твоихъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Но Сигонъ не позволилъ Израилю идти чрезъ свои предјлы; и собралъ Сигонъ весь народъ свой и выступилъ противъ Израиля въ пустыню и дошелъ до Іаацы, и сразился съ Израилемъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'И поразилъ его Израиль остріемъ меча, и взялъ во владјніе землю его отъ Арнона до Іавока, до предјловъ Аммонитскихъ; поелику предјлъ Аммонитянъ былъ укрјпленъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'И взялъ Израиль всј города сіи; и жилъ Израиль во всјхъ городахъ Аморрейскихъ, въ Есевонј, и во всјхъ зависящихъ отъ него.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Ибо Есевонъ былъ городъ Сигона, царя Аморрейскаго: онъ воевалъ съ прежнимъ царемъ Моавитскимъ и взялъ изъ руки его всю землю его до самаго Арнона.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Потому говорятъ приточники: идите въ Есевонъ, да устроятъ и утвердятъ городъ Сигона.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Ибо огонь вышелъ изъ Есевона, пламень изъ города Сигонова, и пожралъ Аръ-Моавъ и владјющихъ высотами Арнопа.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Горе тебј, Моавъ! Погибъ ты, народъ Хамоса! Отдалъ онъ остальныхъ сыновъ своихъ и дочерей своихъ въ плјнъ Аморрейскому царю Сигону.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Мы поразили ихъ стрјлами, погибъ Есевонъ до Дивона. Мы опустошили до Нофы, которая близъ Медевы.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'И жилъ Израиль въ землј Аморрейской.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'И послалъ Моисей высмотрјть Іазеръ, и взяли города зависящіе отъ него, и прогнали Аммореевъ, которые въ нихъ были.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Потомъ поворотили и пошли къ Васану. И выступилъ противъ нихъ Огъ, царь Васанскій, самъ и весь народъ его, на сраженіе къ Едреи.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'И сказалъ Господь Моисею: не бойся его, ибо Я предамъ его, и весь народъ его и всю землю его въ руки твои, и поступишь съ нимъ, какъ поступилъ съ Сигономъ, царемъ Аморрейскимъ, который жилъ въ Есевонј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'И поразили они его и сыновъ его и весь народъ его, такъ что ни одного не осталось, и овладјли землею его.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, '');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'И отправились сыны Израилевы, и остановились на равнинахъ Моава, по ту сторону Іордана, противъ Іерихона.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Валакъ, сынъ Сепфоровъ, видјлъ все, что сдјлалъ Израиль Аморреямъ;');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'и весьма боялись Моавитяне народа сего, потому что онъ былъ многочисленъ, и ужасались Моавитяне сыновъ Израилевыхъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'И сказали Моавитяне старјйшинамъ Мадіамскимъ: этотъ народъ појдаетъ теперь все вокругъ насъ, какъ волъ појдаетъ траву въ полј. Валакъ же, сынъ Сепфоровъ, былъ царемъ Моавитянъ въ то время.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'И послалъ онъ пословъ къ Валааму, сыну Веорову, въ Пефоръ, который на рјкј Евфратј, въ землю сыновъ народа его, чтобы позватъ его, и велјлъ сказать: вотъ народъ вышелъ изъ Египта, вотъ онъ покрылъ лице земли, и живетъ подлј меня.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Итакъ, приди, прокляни мнј народъ сей, ибо онъ сильнје меня: можетъ быть, я тогда могу поразить его и выгоню изъ земли. Я знаю, что кого ты благословишь, тотъ благословенъ, и кого ты проклянешь, тотъ проклятъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'И пошли старјйшины Моавитскіе и старјйшины Мадіамскіе съ подарками въ рукахъ, и пришли къ Валааму, и пересказали ему слова Валаковы.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'И сказалъ онъ имъ: переночуйте здјсь ночь и дамъ вамъ отвјтъ, какъ скажетъ мнј Господь. И старјйшины Моавитскіе остались у Валаама.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'И пришелъ Богъ къ Валааму, и сказалъ: какіе это люди у тебя?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Валаамъ сказалъ Богу: Валакъ, сынъ Сепфоровъ, царь Моавитскій прислалъ ко мнј сказать:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'вотъ народъ вышелъ изъ Египта и покрылъ лице земли, итакъ приди, прокляни мнј его: можетъ быть, я тогда могу сразиться съ нимъ и выгоню его.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Богъ сказалъ Валааму: не ходи съ ними, не проклинай народа сего, ибо онъ благословенъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'И всталъ Валаамъ поутру, и сказалъ князьямъ Валаковымъ: подите въ землю вашу, ибо не хочетъ Господь позволить мнј идти съ вами.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'И встали князья Моавитскіе и пришли къ Валаку, и сказали: не согласился Валаамъ идти съ нами.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Валакъ послалъ еще князей, болје и знаменитје тјхъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'И пришли они къ Валааму, и сказали ему: такъ говоритъ Валакъ, сынъ Сепфоровъ: не откажись придти ко мнј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Я окажу тебј великое почтеніе и сдјлаю все, что ни скажешь мнј. Приди, прокляни мнј народъ сей.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Валаамъ въ отвјтъ на сіе сказалъ рабамъ Валаковымъ: хотя бы Валакъ давалъ мнј полный свой домъ серебра и золота, не могу преступить повелјнія Господа, Бога моего, и сдјлать что либо малое или великое.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Впрочемъ останьтесь здјсь и вы на ночь, и я узнаю, что опять скажетъ мнј Господь.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'И пришелъ Богъ къ Валааму ночью, и сказалъ ему: если люди сіи пришли звать тебя, встань, поди съ ними; но только дјлай то, что я буду говорить тебј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Валаамъ всталъ по утру, осјдлалъ ослицу свою и пошелъ съ князьями Моавитскими.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'И воспылалъ гнјвъ Божій за то, что онъ пошелъ, и сталъ Ангелъ Господень на дорогј, чтобы воспретить ему. Онъ јхалъ на ослицј своей и съ нимъ два слуги его.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'И увидјла ослица Ангела Господня, стоящаго на дорогј съ обнаженнымъ мечемъ въ рукј, и своротила ослица съ дороги, и пошла на поле; а Валаамъ сталъ бить ослицу, чтобы возвратить ее на дорогу.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'И сталъ Ангелъ Господень на узкой дорогј, между двумя виноградниками, гдј съ одной стороны заборъ, и съ другой стороны заборъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Ослица, увидјвъ Ангела Господня, прижалась къ стјнј, и прижала ногу Валаамову къ стјнј; и онъ опять сталъ бить ее.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Ангелъ Господень опять перешелъ и сталъ на тјсномъ мјстј, гдј некуда своротить ни направо, ни налјво.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Ослица, увидјвъ Ангела Господня, упала подъ Валаамомъ, и воспылалъ гнјвъ Валаама, и сталъ онъ бить ослицу жезломъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'И отверзъ Господь уста ослицы, и она сказала Валааму: что я тебј сдјлала, что ты бьешь меня вотъ уже третій разъ?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Валаамъ сказалъ ослицј: за то, что ты ругаешься надо мною; если бы у меня въ рукј былъ мечъ, то я теперь же убилъ бы тебя.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Ослица же сказала Валааму: не я ли твоя ослица, на которой ты јздилъ сначала до сего дня? Имјла ли я привычку такъ поступать съ тобою? Онъ сказалъ: нјтъ. [(Numbers 23:31) И открылъ Господь глаза Валааму, и увидјлъ онъ Ангела Господня стоящаго на дорогј съ обнаженнымъ мечемъ въ рукј, и преклонился, и палъ на лице свое.] [(Numbers 23:32) И сказалъ ему Ангелъ Господень: за что ты билъ ослицу твою вотъ уже три раза? Я вышелъ, чтобы воспретить тебј, потому что путь твой непрямъ предо мною.] [(Numbers 23:33) И ослица, видјвъ меня, своротила отъ меня вотъ уже три раза. Еслибы она не своротила отъ меня, то я тебя убилъ бы, а ее оставилъ бы живою.] [(Numbers 23:34) И сказалъ Валаамъ Ангелу Господню: согрјшилъ я, потому что не зналъ, что ты стоишь противъ меня на дорогј; итакъ, если это непріятно въ очахъ твоихъ, то я возвращусь.] [(Numbers 23:35) И сказалъ Ангелъ Господень Валааму: поди съ людьми сими, толъко говори то, что я буду говорить тебј. И пошелъ Валаамъ съ князьями Валаковыми.] [(Numbers 23:36) Валакъ, услышавъ, что идетъ Валаамъ, вышелъ на встрјчу ему въ городъ Моавитскій, который на предјлахъ Арнона, который на самыхъ предјлахъ.] [(Numbers 23:37) И сказалъ Валакъ Валааму: не посылалъ ли я къ тебј звать тебя? Почему ты не шелъ ко мнј? Неужели я въ самомъ дјлј не могу почтить тебя?] [(Numbers 23:38) И сказалъ Валаамъ Валаку: вотъ, я и пришелъ къ тебј, но могу ли я что сказать? Что вложитъ Богъ во уста мои, то и буду говорить.] [(Numbers 23:39) И пошелъ Валаамъ съ Валакомъ и пришли въ Киріаѕ-Хуцоѕъ.] [(Numbers 23:40) И закололъ Валакъ воловъ и овецъ и послалъ Валааму и князьямъ, которые съ нимъ.] [(Numbers 23:41) На другой день Валакъ взялъ Валаама и возвелъ его на высоты Вааловы, чтобъ онъ увидјлъ оттуда часть парода.]');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'И сказалъ Валаамъ Валаку: построй мнј здјсь семь жертвенниковъ, и представь мнј сюда семь тельцовъ и семь овновъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Валакъ сдјлалъ такъ, какъ говорилъ Валаамъ, и вознесли Валакъ и Валаамъ тельцовъ и овновъ на жертвенники.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'И сказалъ Валаамъ Валаку: постой у всессожженія твоего, а я пойду; можетъ быть Господь выйдетъ мнј на встрјчу, и что Онъ покажетъ мнј, я объявлю тебј. И пошелъ на возвышенное мјсто.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'И встрјтился Богъ съ Валаамомъ, и сей сказалъ ему: семь жертвенниковъ устроилъ я и вознесъ тельцовъ и овновъ на жертвенники.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'И вложилъ Господь слово въ уста Валаамовы, и сказалъ: возвратись къ Валаку и такъ говори.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'И возвратился къ нему, и вотъ онъ стоитъ у всесожженія своего, онъ и всј князья Моавитскіе.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'И произнесъ онъ притчу свою, и сказалъ: Изъ Арама привелъ меня Валакъ, Царь Моава, отъ горъ восточныхъ: приди, прокляни мнј Іакова, приди, изреки зло на Израиля!');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Какъ прокляну я? Богъ не проклинаетъ его, какъ изреку зло? Господь не изрекаетъ зла.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Съ вершины скалъ вижу я его, и съ холмовъ смотрю на него: се народъ живетъ отдјльно и между народами не числится.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Кто изчислитъ песокъ Іакова, и сочтетъ множество Израиля? Да умретъ душа моя смертію праведниковъ, и да будетъ кончина моя, какъ ихъ!');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'И сказалъ Валакъ Валааму: что ты со мною дјлаешь? Я взялъ тебя, чтобы проклясть враговъ моихъ, а ты вотъ благословляешь?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'И отвјчалъ онъ, и сказалъ: не долженъ ли я соблюдать тј слова, которыя влагаетъ Господь во уста мои?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'И сказалъ ему Валакъ: поди со мною на другое мјсто, съ котораго ты увидишь его, часть только увидишь, а всего его не увидишь, и прокляни мнј оттуда.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'И взялъ его на равнину стражей, на вершину горы Фазги, и построилъ семь жертвенниковъ, и вознесъ тельцовъ и овновъ на жертвенники.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'И сказалъ Валаамъ Валаку: постой здјсь у всесожженія твоего, а я пойду туда на встрјчу.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'И встрјтился Господь съ Валаамомъ и вложилъ слово во уста его и сказалъ: возвратись къ Валаку и такъ говори.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'И пришелъ къ нему, и вотъ онъ стоитъ у всесожженія своего, и съ нимъ князья Моавитскіе. И сказалъ ему Валакъ: что говоритъ Господь?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Онъ произнесъ притчу свою и сказалъ: Возстань, Валакъ, и послушай, внимай мнј, сынъ Сепфоровъ!');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Богъ не человјкъ, чтобъ ему лгать, и не сынъ человјческій, чтобы перемјнять Ему мысли. Неужели Онъ что сказалъ, того не сдјлаетъ, и что говорилъ, того не совершитъ?');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Вотъ я началъ благословлять, Онъ благословлялъ, и я не отмјняю сего.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Онъ не усматриваетъ порока во Іаковј и не видитъ беззаконія во Израилј; Господь Богъ его съ нимъ, и трубный царскій звукъ у него.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Богъ ведетъ ихъ изъ Египта, быстрота буйвола у нихъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Нјтъ волшебства на Іакова и нјтъ ворожбы противъ Израиля. Въ свое время скажутъ о Іаковј и Израилј: \"А! что творитъ Богъ.\"');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Се, народъ, какъ львица встаетъ И какъ левъ подымается; Не ляжетъ, пока не съјстъ добычи, и не напьется крови убитыхъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'И сказалъ Валакъ Валааму: ни клясть не кляни его, ни благословлять не благословляй его. [(Numbers 24:26) б И отвјчалъ Валаамъ, и сказалъ Валаку: не говорилъ ли я тебј, что я буду дјлать все то, что скажетъ мнј Господь?] [(Numbers 24:27) И сказалъ Валакъ Валааму: поди, я возьму тебя на другое мјсто; можетъ быть, угодно будетъ Богу и оттуда проклянешь мнј его.] [(Numbers 24:28) И взялъ Валакъ Валаама на верхъ Фегора, стоящаго лицемъ къ пустынј.] [(Numbers 24:29) И сказалъ Валаамъ Валаку: построй мнј здјсь семь жертвенниковъ и представь мнј сюда семь тельцовъ и семь овновъ.] [(Numbers 24:30) И сдјлалъ Валакъ, какъ сказалъ Валаамъ, и вознесъ тельцовъ и овновъ на жертвенники.]');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Валаамъ, видя, что Господу угодно благословлять Израиля, не пошелъ, какъ прежде, для гаданія, но обратился лицемъ своимъ къ пустынј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'И взглянулъ Валаамъ очами своими и увидјлъ Израиля, стоявшаго станомъ по колјнамъ своимъ, и былъ на немъ Духъ Божій.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'И произнесъ онъ притчу свою, и сказалъ: Говоритъ Валаамъ, сынъ Веоровъ, говоритъ мужъ съ открытымъ окомъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Говоритъ слышащій слова Божіи, который видитъ видјнія Вседержителя, падаетъ, но открыты очи его.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Какъ прекрасны шатры твои, Іаковъ, жилища твои, Израиль!');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Разстилаются какъ долины, какъ сады при рјкј, какъ алойныя дерева, насажденныя Господомъ, какъ кедры при водахъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Польется вода изъ ведръ его, и сјмя его будетъ какъ великія воды; Превзойдетъ Агага царь его и возвысится царство его.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'Богъ ведетъ ихъ изъ Египта; Онъ быстръ, какъ буйволъ, пожираетъ народы враждебные ему, раздробляетъ кости ихъ, и стрјлами своими разитъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Преклонился, лежитъ какъ левъ, и какъ львица, кто возбудитъ его? Благословляющій тебя благословенъ, и проклинающій тебя проклятъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'И воспламенился гнјвъ Валака на Валаама, и всплеснулъ руками своими, и сказалъ Валакъ Валааму: я призвалъ тебя проклясть враговъ моихъ, а ты благословляешь ихъ вотъ уже въ третій разъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Итакъ бјги въ свое мјсто; я хотјлъ почтить тебя, но вотъ Господь лишаетъ тебя чести.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'И сказалъ Валаамъ Валаку: не говорилъ ли я и посламъ твоимъ, которыхъ ты посылалъ ко мнј:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'хотя бы давалъ мнј Валакъ полный свой домъ серебра и золота, не могу преступить повелјнія Господня, и дјлать что либо доброе или худое по своему произволу: что скажетъ Господь, то и буду говорить.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Итакъ, вотъ я иду къ народу своему; поди, я возвјщу тебј, что сдјлаетъ народъ сей съ народомъ твоимъ въ послјдствіи времени.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'И произнесъ притчу свою, и сказалъ: Говоритъ Валаамъ, сынъ Веоровъ, говоритъ мужъ съ открытымъ окомъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Говоритъ слышащій слова Божіи, имјющій вјдјніе отъ Всевышняго, который видитъ видјнія Вседержителя, падаетъ, но открыты очи его.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Вижу его, но нынј еще нјтъ; Зрю его, но не близко. Восходитъ звјзда отъ Іакова, и возстаетъ жезлъ отъ Израиля, и разитъ князей Моава, и сокрушаетъ всјхъ сыновъ Сиѕовыхъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Едомъ будетъ подъ владјніемъ, Сеиръ будетъ подъ владјніемъ враговъ своихъ, а Израиль явитъ силу свою. [(Numbers 25:19) Произшедшій отъ Іакова овладјетъ и погубитъ оставшееся отъ города.] [(Numbers 25:20) Потомъ, увидјвъ Амалика, произнесъ притчу свою, и сказалъ: Первый изъ народовъ Амаликъ, но конецъ его гибель!] [(Numbers 25:21) Потомъ, увидјвъ Кенеевъ, произнесъ притчу свою, и сказалъ: крјпко жилище твое и на скалј положено гнјздо твое;] [(Numbers 25:22) Но разоренъ будетъ Каинъ, и наконецъ Ассуръ уведетъ тебя въ плјнъ.] [(Numbers 25:23) И произнесъ притчу свою и сказалъ: Горе, кто уцјлјетъ, когда наведетъ сіе Богъ!] [(Numbers 25:24) Придутъ корабли отъ Киттима, и смирятъ Ассура, и смирятъ Евера, и ему гибель.] [(Numbers 25:25) И всталъ Валаамъ и пошелъ обратно въ свое мјсто, а Валакъ пошелъ своею дорогой.]');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Израиль жилъ въ Ситтимј, и началъ народъ блудодјйствовать съ дочерьми Моава.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Онј приглашали народъ къ жертвамъ боговъ своихъ, и јлъ народъ, и кланялся богамъ ихъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'И прилјпился Израиль къ Ваал-Пеору. И воспламенился гнјвъ Господень на Израиля.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'И сказалъ Господь Моисею: возьми всјхъ начальниковъ народа и повјсь ихъ Господу передъ солнцемъ, и отвратится отъ Израиля ярость гнјва Господня.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'И сказалъ Моисей судьямъ Израилевымъ: убейте каждый своихъ подчиненныхъ, прилјпившихся къ Ваал-Пеору.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'И вотъ, нјкто изъ сыновъ Израилевыхъ пришелъ и привелъ къ братьямъ своимъ Мадіанитянку, въ глазахъ Моисея и въ глазахъ всего общества сыновъ Израилевыхъ, когда они плакали у дверей скиніи собранія.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Финеесъ, сынъ Елеазара, сынъ Аарона, священника, видя сіе, всталъ изъ среды общества и взялъ въ руку свою копье.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'И вошелъ сзади Израильтянина въ спальню, и пронзилъ обоихъ ихъ, Израильтянина и женщину въ чрево ея: и прекратилось пораженіе сыновъ Израилевыхъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Умершихъ же отъ пораженія было двадцать четыре тысячи.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'И говорилъ Господь Моисею, и сказалъ:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Финеесъ, сынъ Елеазара, сына Аарона, священника, отвратилъ ярость Мою отъ сыновъ Израилевыхъ, показавъ среди ихъ ревность свою по Мнј, и Я не истребилъ сыновъ Израилевыхъ въ ревности Моей.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Посему скажи: вотъ, Я даю ему Мой завјтъ мира.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'И будетъ по сему завјту у него и у сјмени его по немъ священство вјчно, за то, что онъ показалъ ревность по Богј своемъ и заступилъ сыновъ Израилевыхъ.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Имя убитаго Израильтянина, который убитъ съ Мадіанитянкою, было Зимрій, сынъ Салу, начальникъ поколјнія Симеонова.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'А имя убитой Мадіанитянки Козби, дочь Цура, который былъ начальникъ племени въ Мадіамскомъ народј.');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'И говорилъ Господь Моисею, и сказалъ:');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'стјсните Мадіанитянамъ, и бейте ихъ');
INSERT INTO `RusMakarij_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'за то, что они непріятельски поступили съ вами въ коварствј своемъ, которымъ они коварствовали вамъ посредствомъ Ваал-Пеора, и посредствомъ Козби, дочери начальника Мадіамскаго, сестры ихъ, убитой въ день пораженія за Ваал-Пеора.');
